    expect(screen.queryByTestId('stdout-running')).toBeNull();
  });

  it.each([
    ['列头选中', { scope: 'column', phase: 'implement' } as DrawerSelection, false],
    [
      '会话步节点（role !== null）',
      { scope: 'node', nodeId: 'run:implement:2:executor:0' } as DrawerSelection,
