    const onClose = vi.fn();
    renderModalLess(world(), { scope: 'column', phase: 'implement' }, { onClose });

    await waitFor(() => expect(screen.getByTestId('detail-drawer') !== null).toBe(true));
    fireEvent.keyDown(document, { key: 'Escape' });

