    expect(onClose, '库自身 dismiss 与兜底不得双触发').toHaveBeenCalledTimes(1);
  });

  it('selection 为 null → 组件返回 null，零 data-modal 节点', () => {
    const { container } = renderModalLess(world(), null);

    expect(container.querySelector('[data-modal]')).toBeNull();
