  it('选中面取数失败降级：read_exec_output reject → 抽屉内错误态不崩、关闭仍可用', async () => {
    const onClose = vi.fn();
    invokeMock.mockImplementation((command: string) =>
      command === 'read_exec_output_delta'
        ? Promise.reject('输出记录读取失败')
        : Promise.resolve(null),
    );
    renderModalLess(
      world([outputNode()]),
