    <StdoutPanel root={root} changeName={CHANGE_NAME} execId={EXEC_ID} status={status} />,
  );
}

/** 面板三态 testid 的在场性快照。 */
function stateIds(): { text: boolean; empty: boolean; running: boolean; error: boolean } {
