    text: screen.queryByTestId('stdout-text') !== null,
    empty: screen.queryByTestId('stdout-empty') !== null,
    running: screen.queryByTestId('stdout-running') !== null,
    error: screen.queryByTestId('stdout-error') !== null,
  };
}

